parameters.jsCode:
const items = $input.all();
const data = items[0]?.json || {};
const transactions = data.transaction_details || [];
const largeAmountThreshold = 500;

return transactions.map(txn => {
  const info = txn.transaction_info || {};
  const payer = txn.payer_info || {};
  const amount = parseFloat(info.transaction_amount?.value || 0);
  const isLarge = Math.abs(amount) >= largeAmountThreshold;

  return {
    json: {
      transactionId: info.transaction_id || '',
      amount: amount,
      currency: info.transaction_amount?.currency_code || 'USD',
      status: info.transaction_status || '',
      type: info.transaction_event_code || '',
      payerName: payer.payer_name?.alternate_full_name || '',
      payerEmail: payer.email_address || '',
      date: info.transaction_initiation_date || '',
      subject: info.transaction_subject || '',
      isLargeAmount: isLarge,
      processedAt: new Date().toISOString()
    }
  };
});

